// bookingGateway.js - domestic vocabulary; no fetch details at the call sites
export function makeBookingGateway(conn = defaultConnection) {
  return {
    async listSlots(length) {
      const raw = await conn("BFSN", length.toMinutes(), false);  // connection seam
      return raw.map(convertSlot);                                // foreign -> domestic
    },
  };
}
async function defaultConnection(code, minutes, urgent) {
  const url = new URL(`${BASE}/availableSlots`);
  url.searchParams.set("equipmentCode", code);
  url.searchParams.set("duration", String(minutes));
  const res = await fetch(url);
  if (!res.ok) throw new BookingError(`booking service ${res.status}`);  // translate once
  return res.json();
}
